            <path d="M2.2 2.4L6.4 1.2L6.4 11.4L2.2 12.6V2.4Z" fill="#E8F54A" />
            <path d="M7.6 4.6L11.8 3.4L11.8 13.6L7.6 14.8V4.6Z" fill="#E8F54A" />
