                    }}
                >
                    <span
                        aria-hidden="true"
                        style={{
                            position: "absolute",
                            inset: "12% 25%",
                            border: "1px solid rgba(103,232,249,0.24)",
                            borderRadius: "50%",
                        }}
                    />
                    <span
                        aria-hidden="true"
                        style={{
